    if (messages.length === 0) {
      return [];
    }
    const orderHashes = messages.map((m) => m.data);
    console.log(tag, `fetching ${orderHashes.length} sale details from storage...`);
    const bulkKeys = orderHashes.map((hash) => ({
      key: hash,
      operator: NET_SEAPORT_ZONE_ADDRESS
    }));
